/* ==========================================================================
   ESTADO Y PERSISTENCIA — ZAP / ARCHIVE (FRAMELESS EDITORIAL BOUTIQUE)
   ========================================================================== */
const STORAGE_KEYS = {
  LIKED: 'bf_tenis_2026_liked',
  DISCARDED: 'bf_tenis_2026_discarded',
  TRM: 'bf_tenis_2026_trm'
};

let state = {
  category: 'ALL', // 'ALL' (Hombre) | 'A' | 'B' | 'C' | 'W' (Mujer 35-38 CO) | 'EXPIRED'
  vibe: 'all',
  quickBrand: 'ALL',
  search: '',
  maxPriceCop: 950000,
  stores: new Set(['Amazon', 'Dafiti Colombia', 'Mercado Libre CO', 'ASICS Colombia', 'Nike Colombia', 'Reebok Colombia', 'Falabella CO']),
  brands: new Set([
    'ASICS', 'Adidas', 'Adidas Originals', 'Adidas Performance', 'Reebok', 'Nike',
    'New Balance', 'Vans', 'Skechers', 'Under Armour', 'Nautica', 'Merrell',
    'HOKA', 'Columbia', 'Altra', 'Brooks', 'Mizuno', 'PUMA', 'Saucony', 'Salomon',
    'FILA', 'Calvin Klein'
  ]),
  onlyWaterproof: false,
  onlyFreeShipping: false,
  onlyBigDiscount: false,
  onlyVerified: true,
  sortBy: 'discount-desc',
  viewMode: 'catalog',
  compactGrid: false,
  trm: Number(localStorage.getItem(STORAGE_KEYS.TRM)) || 3592,
  liked: new Set(JSON.parse(localStorage.getItem(STORAGE_KEYS.LIKED) || '[]')),
  discarded: new Set(JSON.parse(localStorage.getItem(STORAGE_KEYS.DISCARDED) || '[]')),
  compareList: [],
  currentFilteredIds: [],
  quickViewId: null
};

function saveState() {
  localStorage.setItem(STORAGE_KEYS.LIKED, JSON.stringify([...state.liked]));
  localStorage.setItem(STORAGE_KEYS.DISCARDED, JSON.stringify([...state.discarded]));
  localStorage.setItem(STORAGE_KEYS.TRM, String(state.trm));
}

function isExpiredDeal(p) {
  return p.dealStatus === 'soldout' || p.dealStatus === 'no_discount';
}

function isWomenDeal(p) {
  return p.category === 'W' || p.gender === 'women';
}

function getPriceCop(product) {
  if (product.currency === 'COP') return product.salePrice;
  return Math.round(product.salePrice * state.trm);
}

function getRegularPriceCop(product) {
  if (product.currency === 'COP') return product.regularPrice;
  return Math.round(product.regularPrice * state.trm);
}

function getSavingsCop(product) {
  return Math.max(0, getRegularPriceCop(product) - getPriceCop(product));
}

function getDiscountPercent(product) {
  if (!product.regularPrice || product.regularPrice <= product.salePrice) return 0;
  return Math.round(((product.regularPrice - product.salePrice) / product.regularPrice) * 100);
}

function formatCop(amount) {
  return '$' + Math.round(amount).toLocaleString('es-CO');
}

function formatUsd(amount) {
  return '$' + Number(amount).toFixed(0) + ' USD';
}

function getCategoryMeta(cat) {
  switch (cat) {
    case 'A': return { label: 'Futurista' };
    case 'B': return { label: 'Fácil Limpieza' };
    case 'C': return { label: 'Máximo Confort' };
    case 'W': return { label: 'Mujer · Chunky' };
    default: return { label: 'Calzado' };
  }
}

function normalizeStoreGroup(p) {
  const s = ((p.store || '') + ' ' + (p.storeName || '')).toLowerCase();
  if (s.includes('amazon')) return 'Amazon';
  if (s.includes('dafiti')) return 'Dafiti Colombia';
  if (s.includes('mercado libre')) return 'Mercado Libre CO';
  if (s.includes('asics')) return 'ASICS Colombia';
  if (s.includes('nike')) return 'Nike Colombia';
  if (s.includes('reebok')) return 'Reebok Colombia';
  return 'Falabella CO';
}

function getShortStoreName(p) {
  const s = ((p.storeName || '') + ' ' + (p.store || '')).toLowerCase();
  if (s.includes('amazon')) return 'Amazon CO';
  if (s.includes('dafiti')) return 'Dafiti';
  if (s.includes('mercado libre')) return 'ML Oficial';
  if (s.includes('asics')) return 'ASICS.co';
  if (s.includes('nike')) return 'Nike.co';
  if (s.includes('reebok')) return 'Reebok.co';
  if (s.includes('adidas')) return 'Adidas.co';
  if (s.includes('underarmour') || s.includes('under armour')) return 'UA.co';
  if (s.includes('columbia')) return 'Columbia.co';
  if (s.includes('falabella')) return 'Falabella';
  return p.storeName || p.store;
}

function cleanProductTitle(p) {
  let t = (p.name || '').trim();
  t = t.replace(/^Tenis\s+Hombre\s+Lifestyle\s*/i, '');
  t = t.replace(/^Tenis\s+Mujer\s+Lifestyle\s*/i, '');
  t = t.replace(/^Tenis\s+Mujer\s+Outdoor\s*/i, '');
  t = t.replace(/^Tenis\s+Hombre\s+Running\s+/i, '');
  t = t.replace(/^Tenis\s+Running\s+Hombre\s+/i, '');
  t = t.replace(/^Tenis\s+Hombre\s+Under\s+Armour\s+/i, 'Under Armour ');
  t = t.replace(/^Tenis\s+Unisex\s+Under\s+Armour\s+/i, 'Under Armour ');
  t = t.replace(/^Tenis\s+Hombre\s+/i, '');
  t = t.replace(/^Tenis\s+Mujer\s+/i, '');
  t = t.replace(/^Tenis\s+Casual\s+/i, '');
  t = t.replace(/^Zapatillas\s+Hombre\s+/i, '');
  t = t.replace(/\s+Under\s+Armour$/i, '');
  t = t.replace(/\s+Calvin\s+Klein$/i, '');
  return t.trim();
}

function cleanEmojiText(str) {
  if (!str) return '';
  return str
    .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '')
    .replace(/^\s*[·•\-–—]+\s*/, '')
    .trim();
}

function matchesVibe(p, vibe) {
  if (!vibe || vibe === 'all') return true;
  const pct = getDiscountPercent(p);
  if (vibe === 'cloud') return p.category === 'C';
  if (vibe === 'steals') return pct >= 45;
  if (vibe === 'rain') return Boolean(p.waterproof);
  if (vibe === 'sculpt') return p.category === 'A';
  if (vibe === 'amazon') return normalizeStoreGroup(p) === 'Amazon';
  return true;
}

function renderBrandQuickDock() {
  const dock = document.getElementById('brandQuickDock');
  if (!dock) return;

  const basePool = PRODUCTS.filter(p => {
    if (state.discarded.has(p.id)) return false;
    if (state.category === 'EXPIRED') {
      if (!isExpiredDeal(p)) return false;
    } else if (state.category === 'W') {
      if (!isWomenDeal(p) || isExpiredDeal(p)) return false;
    } else {
      if (isExpiredDeal(p) || isWomenDeal(p)) return false;
      if (state.onlyVerified && !p.verified) return false;
      if (state.category !== 'ALL' && p.category !== state.category) return false;
    }
    if (!matchesVibe(p, state.vibe)) return false;
    return true;
  });

  const counts = {};
  basePool.forEach(p => {
    counts[p.brand] = (counts[p.brand] || 0) + 1;
  });

  const sortedBrands = Object.keys(counts).sort((a, b) => counts[b] - counts[a]);
  const totalCount = basePool.length;

  let html = `
    <button class="brand-chip ${state.quickBrand === 'ALL' ? 'active' : ''}" data-brand="ALL">
      <span>Todas</span>
      <span class="brand-chip-count">${totalCount}</span>
    </button>
  `;

  sortedBrands.forEach(brand => {
    const isActive = state.quickBrand === brand;
    html += `
      <button class="brand-chip ${isActive ? 'active' : ''}" data-brand="${brand}">
        <span>${brand}</span>
        <span class="brand-chip-count">${counts[brand]}</span>
      </button>
    `;
  });

  dock.innerHTML = html;

  dock.querySelectorAll('.brand-chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const b = btn.dataset.brand;
      state.quickBrand = (state.quickBrand === b && b !== 'ALL') ? 'ALL' : b;
      renderProducts();
    });
  });
}

function filterProducts() {
  return PRODUCTS.filter(p => {
    if (state.viewMode === 'liked') {
      if (!state.liked.has(p.id)) return false;
    } else if (state.viewMode === 'discarded') {
      if (!state.discarded.has(p.id)) return false;
    } else {
      if (state.discarded.has(p.id)) return false;
    }

    if (state.viewMode === 'catalog') {
      if (state.category === 'EXPIRED') {
        if (!isExpiredDeal(p)) return false;
      } else if (state.category === 'W') {
        if (!isWomenDeal(p) || isExpiredDeal(p)) return false;
      } else {
        if (isExpiredDeal(p) || isWomenDeal(p)) return false;
        if (state.onlyVerified && !p.verified) return false;
        if (state.category !== 'ALL' && p.category !== state.category) return false;
      }
    }

    if (state.category !== 'W' && !matchesVibe(p, state.vibe)) return false;
    if (state.quickBrand !== 'ALL' && p.brand !== state.quickBrand) return false;

    if (state.search.trim() !== '') {
      const q = state.search.toLowerCase();
      const hay = `${p.name} ${p.brand} ${p.desc} ${p.materials} ${p.storeName} ${p.verifiedSizes || ''} ${p.statusReason || ''}`.toLowerCase();
      if (!hay.includes(q)) return false;
    }

    const priceCop = getPriceCop(p);
    if (state.maxPriceCop < 950000 && priceCop > state.maxPriceCop) return false;

    if (!state.stores.has(normalizeStoreGroup(p))) return false;
    if (!state.brands.has(p.brand)) return false;

    if (state.onlyWaterproof && !p.waterproof) return false;
    if (state.onlyFreeShipping && !p.freeShipping) return false;
    if (state.onlyBigDiscount && state.category !== 'EXPIRED' && getDiscountPercent(p) < 35) return false;

    return true;
  }).sort((a, b) => {
    switch (state.sortBy) {
      case 'discount-desc': return getDiscountPercent(b) - getDiscountPercent(a);
      case 'savings-desc': return getSavingsCop(b) - getSavingsCop(a);
      case 'price-asc': return getPriceCop(a) - getPriceCop(b);
      case 'price-desc': return getPriceCop(b) - getPriceCop(a);
      case 'comfort-desc': return (b.comfortScore || 0) - (a.comfortScore || 0);
      default: return 0;
    }
  });
}

function updateCountsAndStats() {
  const activeMen = PRODUCTS.filter(p => !state.discarded.has(p.id) && !isExpiredDeal(p) && !isWomenDeal(p) && (!state.onlyVerified || p.verified));
  const activeWomen = PRODUCTS.filter(p => !state.discarded.has(p.id) && !isExpiredDeal(p) && isWomenDeal(p));
  const expiredCatalog = PRODUCTS.filter(p => !state.discarded.has(p.id) && isExpiredDeal(p));

  const countAll = document.getElementById('countAll');
  const countA = document.getElementById('countA');
  const countB = document.getElementById('countB');
  const countC = document.getElementById('countC');
  const countW = document.getElementById('countW');
  const countExpired = document.getElementById('countExpired');

  if (countAll) countAll.textContent = activeMen.length;
  if (countA) countA.textContent = activeMen.filter(p => p.category === 'A').length;
  if (countB) countB.textContent = activeMen.filter(p => p.category === 'B').length;
  if (countC) countC.textContent = activeMen.filter(p => p.category === 'C').length;
  if (countW) countW.textContent = activeWomen.length;
  if (countExpired) countExpired.textContent = expiredCatalog.length;

  const sizeMeta = document.getElementById('brandSizeMeta');
  if (sizeMeta) {
    sizeMeta.textContent = state.category === 'W'
      ? 'MUJER · TALLAS 35–38 CO (5–7.5 US)'
      : 'CO · TALLAS 41–44 (10–11 US)';
  }

  const likedBadge = document.getElementById('likedCountBadge');
  const discardedBadge = document.getElementById('discardedCountBadge');
  if (likedBadge) likedBadge.textContent = state.liked.size;
  if (discardedBadge) discardedBadge.textContent = state.discarded.size;

  let filterCount = 0;
  if (state.vibe !== 'all') filterCount++;
  if (state.maxPriceCop < 950000) filterCount++;
  if (state.onlyWaterproof) filterCount++;
  if (state.onlyFreeShipping) filterCount++;
  if (state.onlyBigDiscount) filterCount++;
  if (state.stores.size < 7) filterCount++;
  if (state.brands.size < 22) filterCount++;

  const badge = document.getElementById('activeFiltersBadge');
  if (badge) {
    if (filterCount > 0) {
      badge.style.display = 'inline-block';
      badge.textContent = filterCount;
    } else {
      badge.style.display = 'none';
    }
  }
}

function renderProducts() {
  updateCountsAndStats();
  renderBrandQuickDock();

  const grid = document.getElementById('productsGrid');
  const empty = document.getElementById('emptyState');
  const countText = document.getElementById('resultsCountText');
  const expiredBanner = document.getElementById('expiredBanner');
  const womenBanner = document.getElementById('womenBanner');
  const filtered = filterProducts();

  state.currentFilteredIds = filtered.map(p => p.id);

  if (expiredBanner) {
    expiredBanner.style.display = (state.viewMode === 'catalog' && state.category === 'EXPIRED') ? 'flex' : 'none';
  }
  if (womenBanner) {
    womenBanner.style.display = (state.viewMode === 'catalog' && state.category === 'W') ? 'block' : 'none';
  }

  if (state.viewMode === 'liked') {
    countText.innerHTML = `${filtered.length} guardados · <button class="text-link-muted" id="btnBackCatalogInline">Ver activos</button>`;
  } else if (state.viewMode === 'discarded') {
    countText.innerHTML = `${filtered.length} ocultos · <button class="text-link-muted" id="btnBackCatalogInline">Ver activos</button>`;
  } else if (state.category === 'EXPIRED') {
    countText.textContent = `${filtered.length} agotados / sin dto.`;
  } else if (state.category === 'W') {
    countText.textContent = `${filtered.length} pares mujer`;
  } else {
    countText.textContent = `${filtered.length} pares`;
  }

  const backBtn = document.getElementById('btnBackCatalogInline');
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      state.viewMode = 'catalog';
      document.getElementById('btnShowLiked')?.classList.remove('active');
      renderProducts();
    });
  }

  if (filtered.length === 0) {
    grid.style.display = 'none';
    empty.style.display = 'block';
    return;
  }

  grid.style.display = 'grid';
  empty.style.display = 'none';
  grid.classList.toggle('compact-grid', state.compactGrid);

  const HEART_SVG = `<svg class="ico-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
  const HEART_SOLID_SVG = `<svg class="ico-sm" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="1.8"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/></svg>`;
  const X_SVG = `<svg class="ico-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>`;
  const RESTORE_SVG = `<svg class="ico-sm" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><polyline points="1 4 1 10 7 10"/><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/></svg>`;

  grid.innerHTML = filtered.map(p => {
    const discountPct = getDiscountPercent(p);
    const priceCop = getPriceCop(p);
    const regCop = getRegularPriceCop(p);
    const isLiked = state.liked.has(p.id);
    const isDiscarded = state.discarded.has(p.id);
    const isCompared = state.compareList.includes(p.id);
    const expired = isExpiredDeal(p);
    const catMeta = getCategoryMeta(p.category);
    const shortStore = getShortStoreName(p);
    const displayTitle = cleanProductTitle(p);

    const usdEquivalent = p.currency === 'USD'
      ? formatUsd(p.salePrice)
      : `~${formatUsd(p.salePrice / state.trm)}`;

    const rawSizes = p.verifiedSizes
      ? p.verifiedSizes.replace('Tallas en stock hoy:', '').replace('Tallas mujer hoy:', '').replace('Tallas:', '').trim()
      : (isWomenDeal(p) ? '35–38 CO' : '41–44 CO');

    let topBadge = `<span></span>`;
    if (p.dealStatus === 'soldout') {
      topBadge = `<span class="status-tag-expired">Agotado</span>`;
    } else if (p.dealStatus === 'no_discount') {
      topBadge = `<span class="status-tag-nodisc">Sin dto. hoy</span>`;
    } else if (discountPct > 0) {
      topBadge = `<span class="discount-tag">-${discountPct}%</span>`;
    }

    return `
      <article class="product-card ${expired ? 'is-expired' : ''}" data-id="${p.id}">
        <div class="card-image-wrap" data-qv-open="${p.id}">
          <div class="stage-top-bar">
            ${topBadge}

            <div class="stage-actions">
              <button class="icon-btn compare-btn ${isCompared ? 'active' : ''}" data-action="compare" data-id="${p.id}" title="Comparar">
                VS
              </button>
              <button class="icon-btn discard-btn" data-action="discard" data-id="${p.id}" title="${isDiscarded ? 'Restaurar' : 'Ocultar'}">
                ${isDiscarded ? RESTORE_SVG : X_SVG}
              </button>
              <button class="icon-btn like-btn ${isLiked ? 'active' : ''}" data-action="like" data-id="${p.id}" title="Guardar">
                ${isLiked ? HEART_SOLID_SVG : HEART_SVG}
              </button>
            </div>
          </div>

          <img
            src="${p.image}"
            alt="${displayTitle}"
            class="product-img"
            loading="lazy"
            onerror="this.onerror=null; this.src='imagenes/cat-a-1.jpg';"
          />

          ${p.waterproof ? `<span class="stage-waterproof">Waterproof / GTX</span>` : ''}
        </div>

        <div class="card-info">
          <div class="card-eyebrow">
            <div class="eyebrow-left">
              <span class="card-brand">${p.brand}</span>
              <span class="eyebrow-dot">·</span>
              <span class="card-category">${catMeta.label}</span>
            </div>
            <span class="card-store">${shortStore}</span>
          </div>

          <h3 class="card-title" data-qv-open="${p.id}" title="${p.name}">${displayTitle}</h3>

          ${expired && p.statusReason ? `<div class="expired-reason-line">${p.statusReason}</div>` : ''}

          <div class="card-price-row">
            <div class="price-cluster">
              <span class="price-current">${formatCop(priceCop)}</span>
              ${!expired && discountPct > 0 ? `<span class="price-regular">${formatCop(regCop)}</span>` : ''}
            </div>
            <span class="price-usd">${usdEquivalent}</span>
          </div>

          <div class="card-bottom-row">
            <span class="sizes-line ${(!p.verified || expired) ? 'unverified' : ''}" title="${expired ? (p.statusReason || 'Sin stock hoy') : 'Tallas disponibles hoy'}">
              <span class="sizes-dot"></span>
              <span>${expired ? (p.dealStatus === 'no_discount' ? 'Precio regular' : 'Sin stock hoy') : `Talla ${rawSizes}`}</span>
            </span>

            <a href="${p.url}" target="_blank" rel="noopener noreferrer" class="store-link-direct">
              <span>${expired ? 'Revisar ↗' : 'Tienda ↗'}</span>
            </a>
          </div>
        </div>
      </article>
    `;
  }).join('');

  grid.querySelectorAll('.icon-btn').forEach(btn => {
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const id = btn.dataset.id;
      const action = btn.dataset.action;

      if (action === 'like') {
        if (state.liked.has(id)) state.liked.delete(id);
        else state.liked.add(id);
        saveState();
        renderProducts();
      } else if (action === 'discard') {
        if (state.discarded.has(id)) state.discarded.delete(id);
        else {
          state.discarded.add(id);
          state.liked.delete(id);
        }
        saveState();
        renderProducts();
      } else if (action === 'compare') {
        toggleCompareProduct(id);
      }
    });
  });

  grid.querySelectorAll('[data-qv-open]').forEach(el => {
    el.addEventListener('click', () => openQuickView(el.dataset.qvOpen));
  });
}

/* ==========================================================================
   COMPARADOR
   ========================================================================== */
function toggleCompareProduct(id) {
  const idx = state.compareList.indexOf(id);
  if (idx >= 0) {
    state.compareList.splice(idx, 1);
  } else {
    if (state.compareList.length >= 3) {
      state.compareList.shift();
    }
    state.compareList.push(id);
  }
  renderCompareBar();
  renderProducts();
}

function renderCompareBar() {
  const bar = document.getElementById('compareBar');
  const countEl = document.getElementById('compareCount');
  const thumbsEl = document.getElementById('compareThumbs');
  if (!bar) return;

  if (state.compareList.length === 0) {
    bar.style.display = 'none';
    return;
  }

  bar.style.display = 'block';
  countEl.textContent = state.compareList.length;

  thumbsEl.innerHTML = state.compareList.map(id => {
    const p = PRODUCTS.find(x => x.id === id);
    if (!p) return '';
    return `
      <div class="compare-thumb-pill">
        <img src="${p.image}" alt="${p.brand}" />
        <span>${p.brand}</span>
        <button type="button" data-rm-cmp="${p.id}" title="Quitar">&times;</button>
      </div>
    `;
  }).join('');

  thumbsEl.querySelectorAll('[data-rm-cmp]').forEach(btn => {
    btn.addEventListener('click', () => toggleCompareProduct(btn.dataset.rmCmp));
  });
}

function openCompareModal() {
  const modal = document.getElementById('compareModal');
  const wrap = document.getElementById('compareTableWrap');
  if (!modal || !wrap || state.compareList.length === 0) return;

  const items = state.compareList.map(id => PRODUCTS.find(x => x.id === id)).filter(Boolean);

  wrap.innerHTML = `
    <div class="compare-cols">
      ${items.map(p => {
        const pct = getDiscountPercent(p);
        const cop = getPriceCop(p);
        const reg = getRegularPriceCop(p);
        const sav = getSavingsCop(p);
        const catMeta = getCategoryMeta(p.category);
        return `
          <div class="compare-col-card">
            <div class="compare-col-img">
              <img src="${p.image}" alt="${p.name}" />
            </div>
            <div>
              <span class="card-brand">${p.brand} · ${catMeta.label}</span>
              <h4 style="font-size:0.95rem;margin:4px 0 8px;">${cleanProductTitle(p)}</h4>
            </div>
            <div class="compare-row-item"><span>Precio oferta</span><strong>${formatCop(cop)} ${pct > 0 ? `(-${pct}%)` : ''}</strong></div>
            <div class="compare-row-item"><span>Precio regular</span><span>${formatCop(reg)}</span></div>
            <div class="compare-row-item"><span>Ahorro</span><strong style="color:var(--accent-stockx)">${formatCop(sav)}</strong></div>
            <div class="compare-row-item"><span>Tienda</span><strong>${getShortStoreName(p)}</strong></div>
            <div class="compare-row-item"><span>Tallas</span><strong>${p.verifiedSizes ? p.verifiedSizes.replace('Tallas en stock hoy:', '').replace('Tallas mujer hoy:', '') : 'Ver en tienda'}</strong></div>
            <div class="compare-row-item"><span>Materiales</span><span>${p.materials || 'Estándar'}</span></div>
            <a href="${p.url}" target="_blank" rel="noopener noreferrer" class="btn-solid-dark" style="margin-top:8px;">Ir a Tienda ↗</a>
          </div>
        `;
      }).join('')}
    </div>
  `;

  modal.style.display = 'flex';
}

/* ==========================================================================
   FICHA DE PRODUCTO (MODAL)
   ========================================================================== */
function openQuickView(productId) {
  const p = PRODUCTS.find(item => item.id === productId);
  if (!p) return;

  state.quickViewId = p.id;
  const modal = document.getElementById('quickViewModal');
  const discountPct = getDiscountPercent(p);
  const priceCop = getPriceCop(p);
  const regCop = getRegularPriceCop(p);
  const savingsCop = getSavingsCop(p);
  const catMeta = getCategoryMeta(p.category);
  const isLiked = state.liked.has(p.id);
  const expired = isExpiredDeal(p);

  document.getElementById('qvImage').src = p.image;
  document.getElementById('qvImage').alt = p.name;

  const discEl = document.getElementById('qvDiscount');
  if (p.dealStatus === 'soldout') {
    discEl.style.display = 'inline-block';
    discEl.textContent = 'AGOTADO';
  } else if (p.dealStatus === 'no_discount') {
    discEl.style.display = 'inline-block';
    discEl.textContent = 'SIN DESCUENTO HOY';
  } else if (discountPct > 0) {
    discEl.style.display = 'inline-block';
    discEl.textContent = `-${discountPct}%`;
  } else {
    discEl.style.display = 'none';
  }

  document.getElementById('qvBrand').textContent = `${p.brand} · ${getShortStoreName(p)}`;
  document.getElementById('qvCatBadge').textContent = catMeta.label;
  document.getElementById('qvTitle').textContent = cleanProductTitle(p);
  document.getElementById('qvDesc').textContent = expired && p.statusReason
    ? `${p.statusReason}. ${cleanEmojiText(p.desc)}`
    : cleanEmojiText(p.desc);

  const usdDisplay = p.currency === 'USD'
    ? `${formatUsd(p.salePrice)} (Envío gratis directo a Colombia <$200 USD)`
    : `Equivalente aprox: ${formatUsd(p.salePrice / state.trm)}`;

  document.getElementById('qvPriceBox').innerHTML = `
    <div style="display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;">
      <span style="font-size:1.55rem;font-weight:700;font-family:var(--font-mono);color:var(--ink-black)">${formatCop(priceCop)} COP</span>
      ${!expired && discountPct > 0 ? `<span style="text-decoration:line-through;color:var(--ink-subtle);font-family:var(--font-mono)">${formatCop(regCop)} COP</span>` : ''}
    </div>
    <div style="font-size:0.8rem;color:var(--ink-muted);margin-top:4px;">
      ${usdDisplay} ${!expired && savingsCop > 0 ? `· <strong style="color:var(--accent-stockx)">Ahorras ${formatCop(savingsCop)} COP</strong>` : ''}
    </div>
  `;

  document.getElementById('qvSpecsGrid').innerHTML = `
    <div class="spec-box">
      <span>Estado de stock hoy</span>
      <strong>${expired ? (p.statusReason || 'Agotado / Sin descuento') : (p.verifiedSizes ? p.verifiedSizes.replace('Tallas en stock hoy:', '').replace('Tallas mujer hoy:', '') : 'Disponible')}</strong>
    </div>
    <div class="spec-box">
      <span>Tienda Oficial</span>
      <strong>${p.storeName || p.store}</strong>
    </div>
    <div class="spec-box">
      <span>Construcción / Suela</span>
      <strong>${p.materials || 'Construcción original'}</strong>
    </div>
    <div class="spec-box">
      <span>Envío a Colombia</span>
      <strong>${p.freeShipping ? 'Gratis directo sin casillero' : 'Envío nacional directo'}</strong>
    </div>
  `;

  const likeBtn = document.getElementById('qvLikeBtn');
  likeBtn.className = `btn-outline-dark ${isLiked ? 'active' : ''}`;
  likeBtn.textContent = isLiked ? 'Guardado' : 'Guardar';
  likeBtn.onclick = () => {
    if (state.liked.has(p.id)) state.liked.delete(p.id);
    else state.liked.add(p.id);
    saveState();
    openQuickView(p.id);
    renderProducts();
  };

  document.getElementById('qvBuyLink').href = p.url;
  modal.style.display = 'flex';
}

function navigateQuickView(direction) {
  if (!state.quickViewId || state.currentFilteredIds.length === 0) return;
  const idx = state.currentFilteredIds.indexOf(state.quickViewId);
  if (idx === -1) return;
  const nextIdx = (idx + direction + state.currentFilteredIds.length) % state.currentFilteredIds.length;
  openQuickView(state.currentFilteredIds[nextIdx]);
}

/* ==========================================================================
   EXPORTAR LISTA
   ========================================================================== */
function buildExportText() {
  const likedProducts = PRODUCTS.filter(p => state.liked.has(p.id));
  if (likedProducts.length === 0) return 'No tienes pares guardados todavía.';

  const lines = [
    'ZAP / ARCHIVE — PARES GUARDADOS',
    `TRM: $${state.trm} COP/USD | Total: ${likedProducts.length}`,
    '------------------------------------------------------------',
    ''
  ];

  likedProducts.forEach((p, i) => {
    const cop = formatCop(getPriceCop(p));
    const pct = getDiscountPercent(p);
    lines.push(`${i + 1}. [${p.brand}${isWomenDeal(p) ? ' · MUJER' : ''}] ${cleanProductTitle(p)}`);
    lines.push(`   Precio: ${cop} COP (-${pct}%) | Tienda: ${p.storeName}`);
    lines.push(`   Tallas: ${p.verifiedSizes || 'Ver en tienda'}`);
    lines.push(`   Link: ${p.url}`);
    lines.push('');
  });

  return lines.join('\n');
}

function openExportModal() {
  const modal = document.getElementById('exportModal');
  const body = document.getElementById('exportModalBody');
  const likedProducts = PRODUCTS.filter(p => state.liked.has(p.id));

  if (likedProducts.length === 0) {
    body.innerHTML = `<p style="color:var(--ink-muted);padding:16px 0;">Aún no has guardado pares. Usa el ícono de corazón en cualquier zapato.</p>`;
  } else {
    body.innerHTML = likedProducts.map(p => `
      <div class="saved-item-row">
        <div>
          <strong style="font-size:0.88rem;">${p.brand}${isWomenDeal(p) ? ' · Mujer' : ''} — ${cleanProductTitle(p)}</strong>
          <div style="font-size:0.76rem;color:var(--ink-muted)">
            ${formatCop(getPriceCop(p))} COP (-${getDiscountPercent(p)}%) · ${p.storeName}
          </div>
        </div>
        <a href="${p.url}" target="_blank" rel="noopener noreferrer" class="store-link-direct">Tienda ↗</a>
      </div>
    `).join('');
  }

  modal.style.display = 'flex';
}

/* ==========================================================================
   EVENTOS
   ========================================================================== */
function initEvents() {
  document.querySelectorAll('#categoryTabs .nav-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('#categoryTabs .nav-tab').forEach(t => t.classList.remove('active'));
      tab.classList.add('active');
      state.category = tab.dataset.cat;
      state.quickBrand = 'ALL';
      state.viewMode = 'catalog';
      renderProducts();
    });
  });

  document.getElementById('btnBackActiveFromExpired')?.addEventListener('click', () => {
    state.category = 'ALL';
    state.quickBrand = 'ALL';
    document.querySelectorAll('#categoryTabs .nav-tab').forEach(t => {
      t.classList.toggle('active', t.dataset.cat === 'ALL');
    });
    renderProducts();
  });

  document.querySelectorAll('#vibePresetsBar .vibe-option').forEach(chip => {
    chip.addEventListener('click', () => {
      document.querySelectorAll('#vibePresetsBar .vibe-option').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
      state.vibe = chip.dataset.vibe;
      state.viewMode = 'catalog';
      if (state.category === 'EXPIRED' || state.category === 'W') {
        state.category = 'ALL';
        document.querySelectorAll('#categoryTabs .nav-tab').forEach(t => t.classList.toggle('active', t.dataset.cat === 'ALL'));
      }
      renderProducts();
    });
  });

  document.getElementById('searchInput')?.addEventListener('input', e => {
    state.search = e.target.value;
    renderProducts();
  });

  const priceRange = document.getElementById('priceMaxRange');
  const priceLabel = document.getElementById('priceRangeLabel');
  priceRange?.addEventListener('input', e => {
    state.maxPriceCop = Number(e.target.value);
    priceLabel.textContent = state.maxPriceCop >= 950000
      ? 'Hasta $950.000+ COP'
      : `Hasta ${formatCop(state.maxPriceCop)} COP`;
    renderProducts();
  });

  document.getElementById('sortSelect')?.addEventListener('change', e => {
    state.sortBy = e.target.value;
    renderProducts();
  });

  const trmInput = document.getElementById('trmInput');
  if (trmInput) {
    trmInput.value = state.trm;
    trmInput.addEventListener('change', e => {
      const val = Number(e.target.value);
      if (val >= 2000 && val <= 7000) {
        state.trm = val;
        saveState();
        renderProducts();
      }
    });
  }

  const filterSidebar = document.getElementById('filterSidebar');
  const filterBackdrop = document.getElementById('filterDrawerBackdrop');
  const toggleDrawer = (open) => {
    filterSidebar?.classList.toggle('open', open);
    filterBackdrop?.classList.toggle('open', open);
  };
  document.getElementById('btnToggleFilters')?.addEventListener('click', () => toggleDrawer(true));
  document.getElementById('btnCloseFilters')?.addEventListener('click', () => toggleDrawer(false));
  filterBackdrop?.addEventListener('click', () => toggleDrawer(false));

  const btnComfort = document.getElementById('btnViewComfort');
  const btnCompact = document.getElementById('btnViewCompact');
  btnComfort?.addEventListener('click', () => {
    state.compactGrid = false;
    btnComfort.classList.add('active');
    btnCompact?.classList.remove('active');
    renderProducts();
  });
  btnCompact?.addEventListener('click', () => {
    state.compactGrid = true;
    btnCompact.classList.add('active');
    btnComfort?.classList.remove('active');
    renderProducts();
  });

  document.querySelectorAll('#storeFilters input[type="checkbox"]').forEach(cb => {
    cb.addEventListener('change', () => {
      if (cb.checked) state.stores.add(cb.value);
      else state.stores.delete(cb.value);
      renderProducts();
    });
  });

  const brandCheckboxes = document.querySelectorAll('#brandFilters input[type="checkbox"]');
  brandCheckboxes.forEach(cb => {
    cb.addEventListener('change', () => {
      if (cb.checked) state.brands.add(cb.value);
      else state.brands.delete(cb.value);
      renderProducts();
    });
  });

  document.getElementById('btnSelectAllBrands')?.addEventListener('click', () => {
    brandCheckboxes.forEach(cb => { cb.checked = true; state.brands.add(cb.value); });
    renderProducts();
  });

  document.getElementById('btnClearBrands')?.addEventListener('click', () => {
    brandCheckboxes.forEach(cb => { cb.checked = false; state.brands.delete(cb.value); });
    renderProducts();
  });

  document.getElementById('verifiedOnly')?.addEventListener('change', e => {
    state.onlyVerified = e.target.checked;
    renderProducts();
  });
  document.getElementById('filterWaterproof')?.addEventListener('change', e => {
    state.onlyWaterproof = e.target.checked;
    renderProducts();
  });
  document.getElementById('filterFreeShipping')?.addEventListener('change', e => {
    state.onlyFreeShipping = e.target.checked;
    renderProducts();
  });
  document.getElementById('filterBigDiscount')?.addEventListener('change', e => {
    state.onlyBigDiscount = e.target.checked;
    renderProducts();
  });

  const btnLiked = document.getElementById('btnShowLiked');
  const btnDiscarded = document.getElementById('btnShowDiscarded');

  btnLiked?.addEventListener('click', () => {
    state.viewMode = state.viewMode === 'liked' ? 'catalog' : 'liked';
    btnLiked.classList.toggle('active', state.viewMode === 'liked');
    renderProducts();
  });

  btnDiscarded?.addEventListener('click', () => {
    state.viewMode = state.viewMode === 'discarded' ? 'catalog' : 'discarded';
    toggleDrawer(false);
    renderProducts();
  });

  const resetAllFilters = (e) => {
    if (e) e.preventDefault();
    state.category = 'ALL';
    state.vibe = 'all';
    state.quickBrand = 'ALL';
    state.search = '';
    state.maxPriceCop = 950000;
    state.onlyWaterproof = false;
    state.onlyFreeShipping = false;
    state.onlyBigDiscount = false;
    state.onlyVerified = true;
    state.viewMode = 'catalog';

    const sInput = document.getElementById('searchInput');
    if (sInput) sInput.value = '';
    if (priceRange) priceRange.value = 950000;
    if (priceLabel) priceLabel.textContent = 'Hasta $950.000 COP';

    const verCb = document.getElementById('verifiedOnly');
    if (verCb) verCb.checked = true;
    document.getElementById('filterWaterproof').checked = false;
    document.getElementById('filterFreeShipping').checked = false;
    document.getElementById('filterBigDiscount').checked = false;

    document.querySelectorAll('#storeFilters input[type="checkbox"]').forEach(cb => {
      cb.checked = true;
      state.stores.add(cb.value);
    });
    brandCheckboxes.forEach(cb => {
      cb.checked = true;
      state.brands.add(cb.value);
    });

    document.querySelectorAll('#categoryTabs .nav-tab').forEach(t => {
      t.classList.toggle('active', t.dataset.cat === 'ALL');
    });
    document.querySelectorAll('#vibePresetsBar .vibe-option').forEach(c => {
      c.classList.toggle('active', c.dataset.vibe === 'all');
    });

    btnLiked?.classList.remove('active');
    renderProducts();
  };

  document.getElementById('btnLogoReset')?.addEventListener('click', resetAllFilters);
  document.getElementById('btnResetFilters')?.addEventListener('click', resetAllFilters);
  document.getElementById('btnEmptyReset')?.addEventListener('click', resetAllFilters);

  document.getElementById('btnClearCompare')?.addEventListener('click', () => {
    state.compareList = [];
    renderCompareBar();
    renderProducts();
  });
  document.getElementById('btnOpenCompare')?.addEventListener('click', openCompareModal);
  document.getElementById('btnCloseCompareModal')?.addEventListener('click', () => {
    document.getElementById('compareModal').style.display = 'none';
  });

  const qvModal = document.getElementById('quickViewModal');
  document.getElementById('btnCloseQuickView')?.addEventListener('click', () => {
    qvModal.style.display = 'none';
    state.quickViewId = null;
  });
  document.getElementById('qvPrevBtn')?.addEventListener('click', () => navigateQuickView(-1));
  document.getElementById('qvNextBtn')?.addEventListener('click', () => navigateQuickView(1));
  qvModal?.addEventListener('click', e => {
    if (e.target.id === 'quickViewModal') {
      qvModal.style.display = 'none';
      state.quickViewId = null;
    }
  });

  document.addEventListener('keydown', e => {
    if (qvModal && qvModal.style.display === 'flex') {
      if (e.key === 'Escape') {
        qvModal.style.display = 'none';
        state.quickViewId = null;
      } else if (e.key === 'ArrowRight') {
        navigateQuickView(1);
      } else if (e.key === 'ArrowLeft') {
        navigateQuickView(-1);
      }
    }
  });

  document.getElementById('btnExportLiked')?.addEventListener('click', openExportModal);
  document.getElementById('btnCloseModal')?.addEventListener('click', () => {
    document.getElementById('exportModal').style.display = 'none';
  });

  document.getElementById('btnCopyClipboard')?.addEventListener('click', () => {
    navigator.clipboard.writeText(buildExportText()).then(() => {
      const btn = document.getElementById('btnCopyClipboard');
      const orig = btn.textContent;
      btn.textContent = 'Copiado';
      setTimeout(() => (btn.textContent = orig), 2000);
    });
  });

  document.getElementById('btnDownloadTxt')?.addEventListener('click', () => {
    const blob = new Blob([buildExportText()], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'zap-archive-guardados.txt';
    a.click();
    URL.revokeObjectURL(url);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  initEvents();
  renderProducts();
});
